// Mock of the control API (pipeline/kg_pipeline/control) for the admin e2e specs.
// Every JSON shape comes from the fixtures that the real API wrote (tests/fixtures/control/*.json,
// generated by pipeline/tests/test_control_contract.py). State is in memory. Secrets are never returned.
//   A run goes queued -> running -> succeeded over a few GET /runs/{id} calls.
//   A source whose name contains "slow" keeps its run running until the run is canceled.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const fx = (name) => JSON.parse(readFileSync(fileURLToPath(new URL(`../tests/fixtures/control/${name}.json`, import.meta.url)), "utf8"));
const SOURCE = fx("source_create");
const RUN = fx("run_start");
const DETAIL = fx("run_detail");
const TEST_OK = fx("source_test");
const TEST_FAIL = fx("source_test_failed");
const AUDIT = fx("audit").items[0];
const ME = fx("me");

const SECRET_KEYS = { git: ["token"], jira: ["email", "api_token"], confluence: ["email", "api_token"], s3: ["access_key_id", "secret_access_key"] };

const sources = new Map(); // id -> { source, secret }
const runs = new Map(); // id -> { run, polls }
const audit = [];
let seq = 0;
const nextId = (prefix) => `${prefix}_${(++seq).toString(16).padStart(12, "0")}`;
const now = () => new Date().toISOString();

function addAudit(action, target, detail) {
  audit.unshift({ ...AUDIT, id: nextId("aud"), at: now(), action, target, detail });
}

function lastRun(sourceId) {
  const all = [...runs.values()].map((r) => r.run).filter((r) => r.source_id === sourceId);
  return all.length ? all[all.length - 1] : null;
}

function publicSource(entry) {
  const s = entry.source;
  return { ...s, has_secret: Object.keys(entry.secret).length > 0, secret_keys: Object.keys(entry.secret), last_run: lastRun(s.id) };
}

function advance(entry) {
  const r = entry.run;
  if (r.status === "queued" || r.status === "running") {
    entry.polls += 1;
    const slow = r.source_name.includes("slow");
    if (r.status === "queued") Object.assign(r, { status: "running", started_at: now() });
    if (entry.polls >= 3 && !slow) Object.assign(r, { status: "succeeded", ended_at: now(), stats: DETAIL.stats });
  }
  return { ...r, log_tail: r.status === "queued" ? [] : DETAIL.log_tail };
}

const err = (status, message) => ({ status, body: { error: message } });

function pickSecret(kind, secret) {
  const out = {};
  for (const k of SECRET_KEYS[kind]) if (secret && typeof secret[k] === "string" && secret[k]) out[k] = "<stored>";
  return out;
}

/** Returns { status, body } for a /api/v1 request, or null when the path is not a control path. */
export function handleControl(method, pathname, args) {
  if (!pathname.startsWith("/api/v1/")) return null;
  const parts = pathname.slice("/api/v1/".length).split("/").filter(Boolean).map(decodeURIComponent);
  const [head, id, action] = parts;
  if (method === "GET" && head === "me") return { status: 200, body: ME };
  if (head === "sources") {
    if (!id) {
      if (method === "GET") return { status: 200, body: { items: [...sources.values()].map(publicSource).sort((a, b) => a.name.localeCompare(b.name)) } };
      if (method === "POST") {
        if (!Object.keys(SECRET_KEYS).includes(args.kind)) return err(400, "kind must be one of: git, s3, confluence, jira");
        if (typeof args.name !== "string" || !/^[a-z0-9][a-z0-9-]{0,62}$/.test(args.name)) return err(400, "name must match [a-z0-9][a-z0-9-]{0,62}");
        if ([...sources.values()].some((e) => e.source.name === args.name)) return err(409, `a source named ${args.name} already exists`);
        const t = now();
        const source = {
          ...SOURCE, id: nextId("src"), kind: args.kind, name: args.name, config: args.config ?? {}, schedule: args.schedule ?? null,
          enabled: args.enabled ?? true, origin: "ui", created_at: t, updated_at: t,
        };
        sources.set(source.id, { source, secret: pickSecret(args.kind, args.secret) });
        addAudit("source.create", source.id, { name: source.name, kind: source.kind, secret_keys: Object.keys(sources.get(source.id).secret) });
        return { status: 201, body: publicSource(sources.get(source.id)) };
      }
    }
    const entry = sources.get(id);
    if (!entry) return err(404, "source not found");
    if (!action) {
      if (method === "GET") return { status: 200, body: publicSource(entry) };
      if (method === "PATCH") {
        for (const k of ["config", "schedule", "enabled"]) if (k in args) entry.source[k] = args[k];
        if (args.secret) entry.secret = pickSecret(entry.source.kind, args.secret);
        entry.source.updated_at = now();
        addAudit("source.update", id, { name: entry.source.name, changed: Object.keys(args) });
        return { status: 200, body: publicSource(entry) };
      }
      if (method === "DELETE") {
        sources.delete(id);
        for (const e of runs.values()) if (e.run.source_id === id) e.run.source_id = null;
        addAudit("source.delete", id, { name: entry.source.name, kind: entry.source.kind });
        return { status: 204, body: null };
      }
    }
    if (action === "test" && method === "POST") {
      const ok = Object.keys(entry.secret).length > 0 || entry.source.kind === "git";
      addAudit("source.test", id, { kind: entry.source.kind, ok });
      return { status: 200, body: ok ? TEST_OK : TEST_FAIL };
    }
    if (action === "run" && method === "POST") {
      if (!entry.source.enabled) return err(409, "source is disabled");
      const active = [...runs.values()].find((r) => r.run.source_id === id && ["queued", "running"].includes(r.run.status));
      if (active) return err(409, `source already has an active run (${active.run.id})`);
      const run = {
        ...RUN, id: nextId("run"), source_id: id, source_name: entry.source.name, kind: entry.source.kind,
        mode: args.mode ?? "incremental", status: "queued", started_at: null, ended_at: null, stats: null,
        dagster_run_id: `dagster-${seq}`, dagster_url: null,
      };
      runs.set(run.id, { run, polls: 0 });
      addAudit("run.start", run.id, { source: run.source_name, kind: run.kind, mode: run.mode });
      return { status: 202, body: run };
    }
  }
  if (head === "runs") {
    if (!id && method === "GET") return { status: 200, body: { items: [...runs.values()].map((e) => e.run).reverse() } };
    const entry = runs.get(id);
    if (!entry) return err(404, "run not found");
    if (!action && method === "GET") return { status: 200, body: advance(entry) };
    if (action === "cancel" && method === "POST") {
      if (!["queued", "running"].includes(entry.run.status)) return err(409, `run is already ${entry.run.status}`);
      Object.assign(entry.run, { status: "canceled", ended_at: now() });
      addAudit("run.cancel", id, { source: entry.run.source_name, kind: entry.run.kind });
      return { status: 200, body: entry.run };
    }
  }
  if (head === "audit" && method === "GET") return { status: 200, body: { items: audit.slice(0, 50) } };
  return err(404, "not found");
}
